#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>

int main() {
  std::vector<int> numbers = {1, 5, 2, 8, 3};
  // Using iterators to find the maximum element
  auto max_element_iterator = std::max_element(numbers.begin(), numbers.end());
  if (max_element_iterator != numbers.end()) {
    std::cout << "Maximum element: " << *max_element_iterator << std::endl;
  }

  //Using iterators with standard output
  std::copy(numbers.begin(), numbers.end(), std::ostream_iterator<int>(std::cout, " "));
  std::cout << std::endl;

  //Range-based for loop (implicitly uses iterators)
  for (int& num : numbers) {
    num *= 2; // Modifying elements in place
  }

    std::copy(numbers.begin(), numbers.end(), std::ostream_iterator<int>(std::cout, " "));
  std::cout << std::endl;
  return 0;
}
